Γ : List Shape
env : TensorPack ℝ Γ
sources modelDim : ℕ
hModel : 0 < modelDim
query : Term Γ [modelDim]
values : Term Γ [sources, modelDim]
⊢ Term.eval env
      (have kernels :=
        {
          run := fun {α} [Storage α] [Context α] env =>
            have normalized :=
              dim fun row => RMSNorm.scalePositive hModel ((Term.eval env values).unstack row) (ones [modelDim]);
            have transposed := normalized.permute (Shape.adjacentSwap [sources, modelDim] 0) [modelDim, sources] ⋯;
            ((Term.eval env query).vecmat transposed).exp };
      kernels.let1
        (have boundKernels := Term.var (Var.last Γ);
        have boundValues := values.weakenRight;
        {
          run := fun {α} [Storage α] [Context α] env =>
            have kernels := Term.eval env boundKernels;
            have denominator := kernels.sum;
            have weights := map (fun weight => weight / denominator) kernels;
            weights.vecmat (Term.eval env boundValues) })) =
    AttnRes.attendPacked hModel (Term.eval env query) (Term.eval env values)

Γ : List Shape
env : TensorPack ℝ Γ
sources modelDim : ℕ
hModel : 0 < modelDim
query : Term Γ [modelDim]
values : Term Γ [sources, modelDim]
⊢ Term.eval
      (Pack.append env
        (Pack.cons
          (Term.eval env
            {
              run := fun {α} [Storage α] [Context α] env =>
                have normalized :=
                  dim fun row => RMSNorm.scalePositive hModel ((Term.eval env values).unstack row) (ones [modelDim]);
                have transposed := normalized.permute (Shape.adjacentSwap [sources, modelDim] 0) [modelDim, sources] ⋯;
                ((Term.eval env query).vecmat transposed).exp })
          Pack.nil))
      (have boundKernels := Term.var (Var.last Γ);
      have boundValues := values.weakenRight;
      {
        run := fun {α} [Storage α] [Context α] env =>
          have kernels := Term.eval env boundKernels;
          have denominator := kernels.sum;
          have weights := map (fun weight => weight / denominator) kernels;
          weights.vecmat (Term.eval env boundValues) }) =
    AttnRes.attendPacked hModel (Term.eval env query) (Term.eval env values)

