KimiK3.CausalScan.run_compose {FirstState SecondState Input Intermediate Output : Type}
  (first : FirstState → Input → FirstState × Intermediate) (second : SecondState → Intermediate → SecondState × Output)
  (firstState : FirstState) (secondState : SecondState) (inputs : List Input) :
  CausalScan.run
      (fun state input =>
        have firstResult := first state.1 input;
        have secondResult := second state.2 firstResult.2;
        ((firstResult.1, secondResult.1), secondResult.2))
      (firstState, secondState) inputs =
    have firstResult := CausalScan.run first firstState inputs;
    have secondResult := CausalScan.run second secondState firstResult.2;
    ((firstResult.1, secondResult.1), secondResult.2)

KimiK3.CausalScan.run_map_output {State Input Prepared Output Finished : Type}
  (step : State → Prepared → State × Output) (prepare : Input → Prepared) (finish : Output → Finished) (state : State)
  (inputs : List Input) :
  CausalScan.run
      (fun current input =>
        have result := step current (prepare input);
        (result.1, finish result.2))
      state inputs =
    have result := CausalScan.run step state (List.map prepare inputs);
    (result.1, List.map finish result.2)

