KimiK3.LanguageModel.run_append {cfg : TextConfig} {decayRank leftLength rightLength : ℕ}
  (model : LanguageModel ℝ cfg decayRank) (state : model.CausalState) (left : Tensor ℝ [leftLength, cfg.hiddenDim])
  (right : Tensor ℝ [rightLength, cfg.hiddenDim]) :
  model.run state (left.concat right) =
    have first := model.run state left;
    have second := model.run first.1 right;
    (second.1, first.2.concat second.2)

KimiK3.CausalScan.run_append {State Input Output : Type} (step : State → Input → State × Output) (state : State)
  (left right : List Input) :
  CausalScan.run step state (left ++ right) =
    have first := CausalScan.run step state left;
    have second := CausalScan.run step first.1 right;
    (second.1, first.2 ++ second.2)

